import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Config/app_config.dart';import '../../../Research/presentation/widgets/custom_search_text_field.dart';import '../widgets/build_sliver_app_bar_home.dart';import '../../../../Core/Utils/Widget/custom_sliver_grid_builder.dart';import '../../../../Core/Utils/Widget/title_box.dart';import '../widgets/offers_builder.dart';class HomePage extends StatelessWidget {  const HomePage({super.key});  @override  Widget build(BuildContext context) {    return CustomScrollView(      physics: AppConfig.physicsCustomScrollView,      shrinkWrap: true,      slivers: [        SliverAppBarHome(),        SliverToBoxAdapter(          child: Padding(            padding: EdgeInsets.symmetric(              horizontal: AppConfig.customPaddingFromRightLeft,            ).r,            child: CustomSearchTextField(),          ),        ),        CustomOffersWidget(),        SliverPadding(          padding: EdgeInsets.symmetric(            horizontal: AppConfig.customPaddingFromRightLeft,          ).r,          sliver: BuildCustomTitleBox(            title: context.local.popular,            isSliver: true,          ),        ),        SliverPadding(          padding: EdgeInsets.symmetric(            horizontal: AppConfig.customPaddingFromRightLeft,          ).r,          sliver: BuildCustomGridBuilder(            isSliver: true,          ),        ),      ],    );  }}